{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "Is Binder really free?",
        "acceptedAnswer": { "@type": "Answer", "text": "Yes. Everything in the app is free: there is no Pro plan, no paid boost, no blurred likes and no artificial daily wall. The product roadmap contains no paid tier." }
      },
      {
        "@type": "Question",
        "name": "Can someone message me before I like them back?",
        "acceptedAnswer": { "@type": "Answer", "text": "No. Only members of an active mutual match can read or send messages. Unmatch and block end the conversation at the server, not just on your screen." }
      },
      {
        "@type": "Question",
        "name": "Does Binder show my exact location or birth date to other users?",
        "acceptedAnswer": { "@type": "Answer", "text": "No. Exact coordinates are stored privately for server-side distance checks and never enter another client. Binder derives your age and a rounded distance server-side." }
      },
      {
        "@type": "Question",
        "name": "Which languages does Binder support?",
        "acceptedAnswer": { "@type": "Answer", "text": "Binder ships fully translated in {{@language-count}} languages and follows the language your phone is already set to. You can override the choice at any time in the app." }
      },
      {
        "@type": "Question",
        "name": "How do I delete my Binder account?",
        "acceptedAnswer": { "@type": "Answer", "text": "From Profile and then Account controls inside the app, or through the public deletion page, which stays available even after you uninstall Binder." }
      }
    ]
  }

